import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"スクラムバン(Scrumban)","description":"スクラムバン(Scrumban)はスクラムの反復的構造とカンバンのフロー管理・WIP制限を結合し、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","frontmatter":{"title":"スクラムバン(Scrumban)","description":"スクラムバン(Scrumban)はスクラムの反復的構造とカンバンのフロー管理・WIP制限を結合し、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバン概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル方法論, アジャイルフレームワーク, カンバン方法論, スクラム方法論, スクラムバンプロセス, スクラムバン運営ガイド, スクラムバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバンの活用事例, スクラムバン導入効果, スクラムバン Jira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化方法論, 反復的作業管理, ボトルネック解決"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン(Scrumban)はスクラムの反復的構造とカンバンのフロー管理・WIP制限を結合し、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/"}]],"sort":200},"headers":[],"relativePath":"ja/agile/index.md","filePath":"ja/agile/index.md","lastUpdated":1784463011000}`),a={name:`ja/agile/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="スクラムバン-scrumban" tabindex="-1">スクラムバン(Scrumban) <a class="header-anchor" href="#スクラムバン-scrumban" aria-label="Permalink to “スクラムバン(Scrumban)”">​</a></h1><blockquote><p><strong>要約一行:</strong> スクラムバンはスクラムの構造（役割/会議/バックログの概念）とカンバンのフロー中心・WIP制限（Work In Progress制限）を結合したプロセスです。スプリントの厳格さの代わりに<strong>フロー(Flow)</strong>と<strong>プル(Pull)</strong>を重視しつつ、必要な箇所にスクラム式の儀式（計画・振り返り）を維持します。</p></blockquote><h2 id="紹介・定義" tabindex="-1">紹介・定義 <a class="header-anchor" href="#紹介・定義" aria-label="Permalink to “紹介・定義”">​</a></h2><p><strong>スクラムバン(Scrumban)</strong>は、ソフトウェア開発およびナレッジワークチームが柔軟にワークフローを管理できるように設計されたハイブリッドプロセスです。</p><ul><li><strong>スクラム</strong>: 反復（スプリント）、固定されたイベント（スプリントプランニング・レビュー・レトロスペクティブ）、明確な役割</li><li><strong>カンバン</strong>: 視覚的ボード、WIP制限、プルベースの作業、継続的改善 スクラムバンは上記2つのアプローチのメリットを取り入れ、<strong>現実的なフローの改善</strong>に焦点を当てます。</li></ul><h2 id="いつスクラムバンを使うのが良いか" tabindex="-1">いつスクラムバンを使うのが良いか？ <a class="header-anchor" href="#いつスクラムバンを使うのが良いか" aria-label="Permalink to “いつスクラムバンを使うのが良いか？”">​</a></h2><ul><li>既存で<strong>スクラム</strong>を使用しているが、頻繁な変更（緊急要請）が多く、スプリントでまとめるのが難しい。</li><li><strong>カンバン</strong>でフローを回しているが、バックログ管理・優先順位・定期的な振り返りのような規律が必要なチーム。</li><li>保守・運用・サポート（運用作業＋新機能開発が混在）チーム。</li><li>予測よりも<strong>継続的デリバリー</strong>(continuous delivery)とフローの最適化を重視する場合。</li></ul><h2 id="コアコンセプト" tabindex="-1">コアコンセプト <a class="header-anchor" href="#コアコンセプト" aria-label="Permalink to “コアコンセプト”">​</a></h2><ol><li><strong>プル(Pull)システム</strong>: 作業はチームが処理可能な時点でのみ開始（次の列に引き込む）。</li><li><strong>WIP（進行中の作業）制限</strong>: 同時に進行する作業数を制限し、マルチタスクを減らして完了を促進。</li><li><strong>視覚化されたボード</strong>: 作業のステータスを明確に示し、ボトルネックを即座に確認。</li><li><strong>定期的な補充(Replenishment) / プランニング</strong>: 必要な時にだけバックログから作業を補充（周期的あるいは臨界点到達時）。</li><li><strong>測定と改善</strong>: サイクルタイム、リードタイム、スループットなどの指標でフローを改善。</li><li><strong>ポリシー(Explicit Policies)</strong>: 列の移動条件、優先順位のルール、Definition of Ready/Doneの明文化。</li></ol><h2 id="スクラム-vs-カンバン-vs-スクラムバン" tabindex="-1">スクラム vs カンバン vs スクラムバン <a class="header-anchor" href="#スクラム-vs-カンバン-vs-スクラムバン" aria-label="Permalink to “スクラム vs カンバン vs スクラムバン”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th style="text-align:right;">スクラム</th><th>カンバン</th><th>スクラムバン</th></tr></thead><tbody><tr><td>反復（スプリント）</td><td style="text-align:right;">あり（固定長）</td><td>なし（継続的フロー）</td><td>選択的 / 短いイテレーションの混用</td></tr><tr><td>WIP制限</td><td style="text-align:right;">暗黙的（スプリントの範囲）</td><td>明示的</td><td>明示的（中核）</td></tr><tr><td>計画方式</td><td style="text-align:right;">スプリントプランニング</td><td>補充/プルベース</td><td>補充 ＋ 必要に応じてプランニング</td></tr><tr><td>役割</td><td style="text-align:right;">PO/SM/Dev</td><td>柔軟（役割なし）</td><td>PO ＋ Flow Manager（あるいはSMの役割維持）</td></tr><tr><td>目標</td><td style="text-align:right;">コミットメント（スプリントの目標）</td><td>フローの最適化</td><td>フローの最適化 ＋ 優先順位管理</td></tr></tbody></table><h2 id="役割と責任" tabindex="-1">役割と責任 <a class="header-anchor" href="#役割と責任" aria-label="Permalink to “役割と責任”">​</a></h2><ul><li><strong>プロダクトオーナー(PO)</strong>: バックログの優先順位、ステークホルダーとの調整、ビジネス価値の定義</li><li><strong>Flow Manager（またはScrum Masterの役割を維持）</strong>: フローの監視、ボトルネック解消のサポート、プロセス改善の促進</li><li><strong>チーム（開発者/テスターなど）</strong>: 定義されたポリシーの遵守、WIP制限内でプル方式による作業の開始/完了</li><li><strong>ステークホルダー</strong>: 要求・フィードバックの提供、レビューへの参加（必要に応じて）</li></ul><blockquote><p>役割はチームの状況に合わせて柔軟に調整してください。重要なのは<strong>フロー管理の責任</strong>が明確でなければならないという点です。</p></blockquote><h2 id="コアアーティファクト・ツール" tabindex="-1">コアアーティファクト・ツール <a class="header-anchor" href="#コアアーティファクト・ツール" aria-label="Permalink to “コアアーティファクト・ツール”">​</a></h2><ul><li><strong>カンバンボード</strong>（物理またはデジタル） — 列とWIP制限を含む</li><li><strong>バックログ（優先順位リスト）</strong> — プル状態の作業候補</li><li><strong>明確なポリシー(Explicit policies)</strong> — 列移動のルール、定義(Ready/Done)</li><li><strong>クラス・オブ・サービス(Classes of Service)</strong> — 緊急/固定日/標準などの優先順位のタイプ</li><li><strong>メトリクスダッシュボード</strong>: サイクルタイム、リードタイム、スループット、CFD（累積フロー図）</li></ul><h2 id="ボードレイアウト" tabindex="-1">ボードレイアウト <a class="header-anchor" href="#ボードレイアウト" aria-label="Permalink to “ボードレイアウト”">​</a></h2><p>基本的なスクラムバンボード（例）：</p><table tabindex="0"><thead><tr><th>列</th><th>説明</th><th style="text-align:right;">推奨WIP制限</th></tr></thead><tbody><tr><td>Backlog</td><td>優先順位が付けられたすべての作業</td><td style="text-align:right;">—</td></tr><tr><td>Ready</td><td>開始可能な作業（Doingへ移動可能な状態）</td><td style="text-align:right;">—</td></tr><tr><td>Doing / In Progress</td><td>実際の作業中</td><td style="text-align:right;">3</td></tr><tr><td>Code Review</td><td>レビュー待ち</td><td style="text-align:right;">2</td></tr><tr><td>Testing</td><td>QA/検証</td><td style="text-align:right;">2</td></tr><tr><td>Done</td><td>完了</td><td style="text-align:right;">—</td></tr></tbody></table><p><strong>シンプルなASCIIボード:</strong></p><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Backlog -&gt; Ready -&gt; [Doing (WIP 3)] -&gt; Code Review (WIP 2) -&gt; Testing (WIP 2) -&gt; Done</span></span></code></pre></div><h2 id="ワークフロールールの例" tabindex="-1">ワークフロールールの例 <a class="header-anchor" href="#ワークフロールールの例" aria-label="Permalink to “ワークフロールールの例”">​</a></h2><div class="language-text"><button title="Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Policy: プル条件（Doing列へ移動）</span></span>
<span class="line"><span>- カードがReady列にあり、Doing列のWIP &lt; WIP制限</span></span>
<span class="line"><span>- 該当する作業の&#39;Definition of Ready&#39;を満たしている（要件/テストケース/デザインなど）</span></span>
<span class="line"><span>- 必要なリソース（テスター/レビュアー）の可用性を確認</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Policy: Definition of Done（完了基準）</span></span>
<span class="line"><span>- コードがマージされ、ビルド成功</span></span>
<span class="line"><span>- 自動/手動テストに合格</span></span>
<span class="line"><span>- デプロイ（またはQA引き継ぎ）のドキュメント化完了</span></span></code></pre></div><p><strong>Classes of Serviceの例</strong></p><ul><li><strong>Expedite（急行）</strong>: 即時処理（作業の優先順位最上位、WIPの例外を許可）</li><li><strong>Fixed Date（固定日）</strong>: 特定の日付が必要 — スケジュールの監視が必要</li><li><strong>Standard（標準）</strong>: 一般的なリクエスト</li><li><strong>Intangible（無形）</strong>: 技術的負債などの長期的価値</li></ul><h2 id="イベントと推奨周期" tabindex="-1">イベントと推奨周期 <a class="header-anchor" href="#イベントと推奨周期" aria-label="Permalink to “イベントと推奨周期”">​</a></h2><ul><li><strong>デイリースタンドアップ（毎日、10〜15分）</strong>: フロー中心に（何をしているかよりもボトルネック/ブロッカーの共有）</li><li><strong>補充(Replenishment) / バックログリファインメント（週1回または必要に応じて）</strong>: Ready列を補充 — 優先順位の再整備</li><li><strong>プランニング（必要に応じて）</strong>: 大きな作業（エピック）の分解または代替計画 — 短く。</li><li><strong>レトロスペクティブ（2〜4週周期）</strong>: プロセス改善、WIP制限の調整検討</li><li><strong>サービスデリバリーレビュー / Opsレビュー（月次）</strong>: SLA・SLE・指標のレビュー</li></ul><blockquote><p>スクラムのようにすべての会議を厳格に決めておく必要はありません。<strong>フローを妨げる箇所</strong>が見えたら会議を導入してください。</p></blockquote><h2 id="見積もり・計画方法" tabindex="-1">見積もり・計画方法 <a class="header-anchor" href="#見積もり・計画方法" aria-label="Permalink to “見積もり・計画方法”">​</a></h2><ul><li><strong>ストーリーポイントの維持</strong>: スクラムから移行するチームに適合。スループットに対する予測に有利。</li><li><strong>No Estimates（見積もり省略）</strong>: カードの単純カウント ＋ サイクルタイム/スループットで予測。</li><li><strong>バケット（期間ベース）計画</strong>: 月別に完了可能な作業量(throughput)を基準に補充。</li><li><strong>推奨</strong>: 重い見積もり活動を減らし、<strong>実際のデータ（サイクルタイム、スループット）</strong>で予測してください。</li></ul><h2 id="コアメトリクス-定義・活用" tabindex="-1">コアメトリクス（定義・活用） <a class="header-anchor" href="#コアメトリクス-定義・活用" aria-label="Permalink to “コアメトリクス（定義・活用）”">​</a></h2><ul><li><strong>リードタイム(Lead Time)</strong> = カードがバックログ（または作成）された時点 → 完了時点</li><li><strong>サイクルタイム(Cycle Time)</strong> = 作業開始(Doing) → 完了</li><li><strong>スループット(Throughput)</strong> = 特定の期間内に完了したカード数</li><li><strong>WIP（平均進行中の作業数）</strong></li><li><strong>累積フロー図(Cumulative Flow Diagram, CFD)</strong>: 各列の累積領域でボトルネック・フローの変化を視覚化</li><li><strong>サービスレベル期待値(SLE)</strong>: 例: 85%の作業が10日以内に完了すること</li></ul><p><strong>参考活用法</strong></p><ul><li>リトルの法則(Little’s Law): <code>WIP = Throughput × Cycle Time</code>（平均値を使用） — 予測および限界の把握に有用</li><li>目標: サイクルタイムの安定化 → 予測可能性の増加</li></ul><h2 id="スクラムからスクラムバンへ" tabindex="-1">スクラムからスクラムバンへ <a class="header-anchor" href="#スクラムからスクラムバンへ" aria-label="Permalink to “スクラムからスクラムバンへ”">​</a></h2><ol><li><strong>現在のプロセスのマッピング</strong>: どのような仕事がどのように流れるかを視覚化</li><li><strong>ボードの構成</strong>: 最小限の列で開始（Ready → Doing → QA → Done）</li><li><strong>WIP制限の設定</strong>: 保守的に開始（例: Doing = チームメンバー数 ÷ 2）</li><li><strong>補充ルールの決定</strong>: いつBacklogからReadyに補充するかを決定（週次/閾値）</li><li><strong>データの収集</strong>: サイクルタイム・スループットの収集（2〜4週間）</li><li><strong>調整の反復</strong>: 振り返りでWIP・列・ポリシーを調整</li></ol><h2 id="カンバン-スクラムバン導入チェックリスト" tabindex="-1">カンバン/スクラムバン導入チェックリスト <a class="header-anchor" href="#カンバン-スクラムバン導入チェックリスト" aria-label="Permalink to “カンバン/スクラムバン導入チェックリスト”">​</a></h2><ul><li>[ ] ボードはチームの現実を反映しているか？</li><li>[ ] WIP制限が設定されており、全員が理解しているか？</li><li>[ ] Definition of Ready/Doneがドキュメント化されているか？</li><li>[ ] Replenishmentの周期（またはルール）が決まっているか？</li><li>[ ] デイリースタンドアップでボトルネック中心の議論が行われているか？</li><li>[ ] サイクルタイム・スループット・CFDを収集し分析しているか？</li><li>[ ] クラス・オブ・サービスとポリシーが定義されているか？</li><li>[ ] 定期的なレトロスペクティブでプロセスの変更が反映されているか？</li></ul><h2 id="実践のヒントとベストプラクティス" tabindex="-1">実践のヒントとベストプラクティス <a class="header-anchor" href="#実践のヒントとベストプラクティス" aria-label="Permalink to “実践のヒントとベストプラクティス”">​</a></h2><ul><li><strong>小さく始める</strong>: ボードとWIP制限を小さくし、素早くフィードバックを受ける。</li><li><strong>Stop starting — start finishing</strong>: 新しい作業を始めるよりも進行中の仕事を終わらせる文化。</li><li><strong>WIP違反時のチームの規律</strong>: 即時議論（なぜ違反したのか、ボトルネックの原因把握）。</li><li><strong>視覚的シグナル</strong>: ブロッカー/緊急カードは別の色/ステッカーで表示。</li><li><strong>ポリシーはドキュメント化</strong>: 「いつカードを移動させるか」を明確に書き留める。</li><li><strong>自動化</strong>: CI/CD、自動テストでサイクルタイムを短縮。</li><li><strong>データ駆動の意思決定</strong>: 見積もりよりも実際のサイクルタイム/スループットで計画。</li></ul><h2 id="よくある間違い" tabindex="-1">よくある間違い <a class="header-anchor" href="#よくある間違い" aria-label="Permalink to “よくある間違い”">​</a></h2><ul><li>WIP制限だけを設定して守らない場合</li><li>スクラムの儀式をそのまま維持しつつ、WIP・プルの概念を無視する</li><li>クラスを作って何の基準もなく使用する（優先順位の混乱）</li><li>指標を収集せず「感覚」だけで意思決定する</li><li>列/細分化が多すぎてボードが複雑になる場合</li></ul><h2 id="テンプレート-replenishment会議-シンプルなアジェンダ" tabindex="-1">テンプレート: Replenishment会議（シンプルなアジェンダ） <a class="header-anchor" href="#テンプレート-replenishment会議-シンプルなアジェンダ" aria-label="Permalink to “テンプレート: Replenishment会議（シンプルなアジェンダ）”">​</a></h2><ol><li>先週完了した作業（簡単なレビュー） — 5分</li><li>Ready列の状態確認（優先順位の再並べ替え） — 10〜20分</li><li>WIP制限に対する現在の可用リソースの確認 — 5分</li><li>新規作業のプル決定（優先順位順に補充） — 10〜20分</li><li>ブロッカー / 危険要因の共有 — 5分</li></ol><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><p><strong>Q. スプリントは完全になくなりますか？</strong> A. チームが望めば、短いイテレーション（例: 2週間）を維持しながらスクラムバンの原則を適用できます。重要なのはフローの改善です。</p><p><strong>Q. ストーリーポイントを使い続けるべきですか？</strong> A. 必ずしもそうする必要はありません。スループットとサイクルタイムで予測する方法も多く使用されています。チームの文化・報告の必要性に応じて決定してください。</p><p><strong>Q. WIP制限はどのように決めますか？</strong> A. 保守的に開始します（チームメンバー数を基準とするか、または過去のスループットから推定）。制限を守りながら段階的に調整します。</p><h2 id="適用例" tabindex="-1">適用例 <a class="header-anchor" href="#適用例" aria-label="Permalink to “適用例”">​</a></h2><ul><li>チームメンバー5人 → Doing WIP = 3（同時作業の制限）</li><li>Replenishment : 週1回（月曜日）</li><li>Retrospective: 2週間ごと（オンライン・オフライン混合）</li><li>指標: 週次スループット ＋ 4週累積サイクルタイムの観察</li></ul><h2 id="締めくくり-—-スタートガイド" tabindex="-1">締めくくり — スタートガイド <a class="header-anchor" href="#締めくくり-—-スタートガイド" aria-label="Permalink to “締めくくり — スタートガイド”">​</a></h2><ol><li><strong>ボードを作り</strong>、</li><li><strong>WIP制限を定め</strong>、</li><li><strong>プル(Pull)のルールとDefinitionをドキュメント化</strong>した後、</li><li><strong>データ（サイクルタイム・スループット）を2〜4週間収集</strong>し、<strong>レトロスペクティブで調整</strong>してください。</li></ol>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};